1975: // A deterministic, bounded M1 front-end model.  The caller owns dynamic
1976: // instruction completion; this class only owns admission and Tag scheduling.
1977: class paper_frontend {
1978:  public:
1979:   explicit paper_frontend(config cfg) : m_cfg(cfg) {
1980:     check_tag_hash_bankrow(cfg.tag_hash_bankrow, false, cfg.finite_service,
1981:                            cfg.logical_sets, cfg.tag_banks);
1982:     check_progressive_wakeup_mode(cfg.progressive_wakeup,
1983:         static_cast<unsigned>(mode::PAPER_BASE), cfg.finite_service);
1984:     assert(m_cfg.pib_entries > 0);
1985:     assert(m_cfg.tag_banks > 0);
1986:     assert(m_cfg.tag_requests_per_bank_per_cycle > 0);
1987:     assert(m_cfg.tag_requests_per_cycle > 0);
1988:   }
1989: 
1990:   bool enabled() const { return m_cfg.selected_mode != mode::LEGACY; }
1991: 
1992:   bool try_admit(uint64_t dynamic_instruction_id) {
1993:     if (!enabled()) return true;
1994:     if (m_live_instructions.count(dynamic_instruction_id)) return true;
1995:     if (m_live_instructions.size() >= m_cfg.pib_entries) {
1996:       ++m_pib_full_events;
1997:       ++m_pib_full_stall_cycles;
1998:       ++m_nonexclusive_pib_full_cycles;
1999:       ++m_frontend_stall_cycles;
2000:       return false;
2001:     }
2002:     m_live_instructions.insert(dynamic_instruction_id);
2003:     ++m_admits;
2004:     m_pib_peak = std::max(m_pib_peak, m_live_instructions.size());
2005:     return true;

